"""Validated shapes for records generated by the local Muse preparation pipeline."""

from __future__ import annotations

from pydantic import BaseModel, ConfigDict


class MuseBatchSource(BaseModel):
    """One source record emitted in a prepared Muse annotation batch."""

    model_config = ConfigDict(extra="forbid", frozen=True)

    id: str
    text: str
    dataset_identity: str
    source_index: int
    metadata: dict[str, str | int | float | bool]
